"use client";

import { cn } from "@/lib/utils";
import {
  Bot,
  CheckCheck,
  MessageSquare,
  Send,
  Sparkles,
  X,
} from "lucide-react";
import React, { useEffect, useRef, useState } from "react";
import { springLinear } from "./motion-curves";

export interface ChatMessage {
  id: string;
  text: string;
  sender: "user" | "agent";
  timestamp: string;
}

export interface FloatingContactButtonProps
  extends React.HTMLAttributes<HTMLDivElement> {
  position?: "bottom-right" | "bottom-left";
  containerMode?: "fixed" | "absolute";
  title?: string;
  subtitle?: string;
  avatarUrl?: string;
  defaultOpen?: boolean;
  localStorageKey?: string;
  defaultAccentColor?: string;
  initialMessages?: ChatMessage[];
  onSendMessage?: (message: string) => void;
}

// ==========================================
// MOTION
// The panel rises in and sinks out (0.22s, cubic-bezier(.16,1,.3,1)); each
// message and the typing bubble fade and settle in as they mount; the launcher
// swells on hover and dips on press; its icon turns out, then the other turns
// in (0.15s each). The springs are CSS `linear()` curves generated from the
// same stiffness/damping.
// ==========================================
const RISE_SPRING = springLinear({ stiffness: 500, damping: 25 });
const SCALE_SPRING = springLinear({ stiffness: 550, damping: 30 });
const PANEL_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const FADE_EASE = "cubic-bezier(0.25, 0.1, 0.35, 1)";
// Tailwind's `transition-colors duration-300`, which the panel and launcher
// carry: repeated here because their own transitions replace the property.
const COLOR_TRANSITIONS = [
  "color",
  "background-color",
  "border-color",
  "outline-color",
  "text-decoration-color",
  "fill",
  "stroke",
  "--tw-gradient-from",
  "--tw-gradient-via",
  "--tw-gradient-to",
]
  .map((property) => `${property} 300ms cubic-bezier(0.4, 0, 0.2, 1)`)
  .join(", ");

const FCB_CSS = `
.fcb-panel {
  transition: ${COLOR_TRANSITIONS}, opacity 0.22s ${PANEL_EASE},
    translate 0.22s ${PANEL_EASE}, scale 0.22s ${PANEL_EASE};
}
.fcb-panel[data-state="closed"] { opacity: 0; translate: 0 16px; scale: 0.96; }
@keyframes fcb-fade-in { from { opacity: 0; } }
@keyframes fcb-rise { from { translate: 0 6px; } }
@keyframes fcb-pop { from { scale: 0.9; } }
.fcb-message {
  animation: fcb-fade-in 0.3s ${FADE_EASE},
    fcb-rise ${RISE_SPRING.duration}ms ${RISE_SPRING.easing};
}
.fcb-typing {
  animation: fcb-fade-in 0.3s ${FADE_EASE},
    fcb-pop ${SCALE_SPRING.duration}ms ${SCALE_SPRING.easing};
}
.fcb-launcher {
  transition: ${COLOR_TRANSITIONS},
    scale ${SCALE_SPRING.duration}ms ${SCALE_SPRING.easing};
}
@media (hover: hover) {
  .fcb-launcher:hover { scale: 1.05; }
}
.fcb-launcher:active { scale: 0.95; }
.fcb-icon {
  transition: rotate 0.15s cubic-bezier(0, 0, 0.58, 1),
    opacity 0.15s cubic-bezier(0, 0, 0.58, 1);
}
.fcb-icon[data-icon="close"][data-leaving] { rotate: 90deg; opacity: 0; }
.fcb-icon[data-icon="open"][data-leaving] { rotate: -90deg; opacity: 0; }
@starting-style {
  .fcb-panel[data-state="open"] { opacity: 0; translate: 0 16px; scale: 0.96; }
  .fcb-icon[data-icon="close"] { rotate: -90deg; opacity: 0; }
  .fcb-icon[data-icon="open"] { rotate: 90deg; opacity: 0; }
}
`;

function resolveColor(c: string): string {
  if (!c || c === "primary" || c === "default") return "var(--primary)";
  if (
    c.startsWith("#") ||
    c.startsWith("rgb") ||
    c.startsWith("hsl") ||
    c.startsWith("var(")
  )
    return c;
  const colorMap: Record<string, string> = {
    indigo: "#6366f1",
    rose: "#f43f5e",
    emerald: "#10b981",
    zinc: "#18181b",
    amber: "#f59e0b",
    violet: "#8b5cf6",
    cyan: "#06b6d4",
    blue: "#3b82f6",
  };
  return colorMap[c] || "var(--primary)";
}

function hexToRgba(hex: string, alpha: number): string {
  if (!hex) return `rgba(99, 102, 241, ${alpha})`;
  const resolved = resolveColor(hex);
  if (resolved.startsWith("var("))
    return `color-mix(in srgb, ${resolved} ${alpha * 100}%, transparent)`;
  if (/^#([A-Fa-f0-9]{3}){1,2}$/.test(resolved)) {
    let digits = resolved.substring(1);
    if (digits.length === 3)
      digits = digits
        .split("")
        .map((d) => d + d)
        .join("");
    const packed = parseInt(digits, 16);
    return `rgba(${(packed >> 16) & 255},${(packed >> 8) & 255},${packed & 255},${alpha})`;
  }
  return resolved;
}

export const FloatingContactButtonBlock = React.forwardRef<
  HTMLDivElement,
  FloatingContactButtonProps
>(
  (
    {
      position = "bottom-right",
      containerMode = "fixed",
      title = "Chat with us",
      subtitle = "We typically reply in a few minutes",
      avatarUrl = "https://res.cloudinary.com/dodndg7ai/image/upload/f_webp,q_auto,w_250,c_limit/v1790150483/photo-1534528741775-53994a69daeb-1790150482280.jpg",
      defaultOpen = false,
      localStorageKey = "primaryColor",
      defaultAccentColor = "var(--primary)",
      initialMessages = [
        {
          id: "1",
          text: "Hi there! 👋 How can we help you build something amazing today?",
          sender: "agent",
          timestamp: "Just now",
        },
      ],
      onSendMessage,
      className,
      ...props
    },
    ref,
  ) => {
    const [isOpen, setIsOpen] = useState(defaultOpen);
    const [messages, setMessages] = useState<ChatMessage[]>(initialMessages);
    const [inputValue, setInputValue] = useState("");
    const [isTyping, setIsTyping] = useState(false);
    const [accentColor, setAccentColor] = useState<string>(defaultAccentColor);

    // The panel stays mounted after closing until its exit has played.
    const [panelMounted, setPanelMounted] = useState(isOpen);
    if (isOpen && !panelMounted) setPanelMounted(true);

    // The launcher shows one icon at a time: the current one turns out, and
    // only then does the next one turn in.
    const wantedIcon = isOpen ? "close" : "open";
    const [shownIcon, setShownIcon] = useState(wantedIcon);
    const iconLeaving = shownIcon !== wantedIcon;

    // Backstops for when no transitionend arrives (e.g. a hidden tab).
    useEffect(() => {
      if (isOpen || !panelMounted) return;
      const timer = setTimeout(() => setPanelMounted(false), 320);
      return () => clearTimeout(timer);
    }, [isOpen, panelMounted]);

    useEffect(() => {
      if (!iconLeaving) return;
      const timer = setTimeout(() => setShownIcon(wantedIcon), 250);
      return () => clearTimeout(timer);
    }, [iconLeaving, wantedIcon]);

    // Sandboxed scroll ref: Replaces scrollIntoView to prevent page jumps
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      if (typeof window === "undefined") return;

      const loadColor = () => {
        let foundColor: string | null = null;
        const knownKeys = [
          localStorageKey,
          "primaryColor",
          "docs-theme-color",
          "theme-color",
          "accentColor",
          "color",
        ];

        for (const k of knownKeys) {
          if (!k) continue;
          try {
            const val = localStorage.getItem(k);
            if (val) {
              const cleaned = val.replace(/['"]/g, "").trim();
              const hexMatch = cleaned.match(
                /#([0-9A-Fa-f]{6}|[0-9A-Fa-f]{3})\b/,
              );
              if (hexMatch) {
                foundColor = hexMatch[0];
                break;
              }
            }
          } catch {
            // Unreadable stylesheet (cross-origin): fall through to the default.
          }
        }

        const targetColor = foundColor || defaultAccentColor;
        setAccentColor((prev) => (prev !== targetColor ? targetColor : prev));
      };

      loadColor();

      const origProtoSetItem = Storage.prototype.setItem;
      Storage.prototype.setItem = function (key: string, value: string) {
        origProtoSetItem.apply(this, [key, value]);
        loadColor();
      };
      const origInstanceSetItem = window.localStorage.setItem;
      window.localStorage.setItem = function (key: string, value: string) {
        origInstanceSetItem.apply(window.localStorage, [key, value]);
        loadColor();
      };

      window.addEventListener("storage", loadColor);
      const intervalId = setInterval(loadColor, 100);

      return () => {
        Storage.prototype.setItem = origProtoSetItem;
        window.localStorage.setItem = origInstanceSetItem;
        window.removeEventListener("storage", loadColor);
        clearInterval(intervalId);
      };
    }, [localStorageKey, defaultAccentColor]);

    // Sandboxed scrolling: Only scrolls inside the chat modal container
    useEffect(() => {
      if (isOpen && scrollContainerRef.current) {
        const el = scrollContainerRef.current;
        el.scrollTo({
          top: el.scrollHeight,
          behavior: "smooth",
        });
      }
    }, [messages, isOpen, isTyping]);

    const handleSend = (e?: React.FormEvent) => {
      if (e) e.preventDefault();
      if (!inputValue.trim()) return;

      const userMsg: ChatMessage = {
        id: Date.now().toString(),
        text: inputValue.trim(),
        sender: "user",
        timestamp: new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
      };

      setMessages((prev) => [...prev, userMsg]);
      setInputValue("");
      if (onSendMessage) onSendMessage(userMsg.text);

      setIsTyping(true);
      setTimeout(() => {
        setIsTyping(false);
        setMessages((prev) => [
          ...prev,
          {
            id: (Date.now() + 1).toString(),
            text: "Thanks for reaching out! A member of our engineering team will review your message and reply shortly.",
            sender: "agent",
            timestamp: new Date().toLocaleTimeString([], {
              hour: "2-digit",
              minute: "2-digit",
            }),
          },
        ]);
      }, 1200);
    };

    const positionClasses =
      position === "bottom-right"
        ? "bottom-4 right-4 sm:bottom-6 sm:right-6"
        : "bottom-4 left-4 sm:bottom-6 sm:left-6";

    const modalAlignmentClasses =
      position === "bottom-right"
        ? "right-0 origin-bottom-right"
        : "left-0 origin-bottom-left";

    const modalWidthClass =
      containerMode === "fixed"
        ? "w-[calc(100vw-2rem)] sm:w-[380px] max-w-[380px]"
        : "w-[380px]";

    const modalHeightClass =
      containerMode === "fixed"
        ? "h-[400px] sm:h-[480px] max-h-[calc(100vh-6rem)]"
        : "h-[480px]";

    const activeBgGlow = hexToRgba(accentColor, 0.25);

    // Auto-scale: shrink the entire widget when its parent container is narrow
    const wrapperRef = useRef<HTMLDivElement>(null);
    const [autoScale, setAutoScale] = useState(1);

    useEffect(() => {
      if (containerMode !== "absolute") return;
      const el = wrapperRef.current;
      if (!el) return;
      const parent = el.offsetParent as HTMLElement | null;
      if (!parent) return;

      const observer = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const w = entry.contentRect.width;
          // Start scaling when container is narrower than 460px
          setAutoScale(Math.min(1, Math.max(0.5, w / 460)));
        }
      });
      observer.observe(parent);
      return () => observer.disconnect();
    }, [containerMode]);

    const mergedRef = (node: HTMLDivElement | null) => {
      (wrapperRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
    };

    return (
      <div
        ref={mergedRef}
        className={cn(
          "pointer-events-none select-none",
          containerMode === "fixed" ? "fixed z-50" : "absolute z-[5]",
          positionClasses,
          "w-14 h-14 sm:w-16 sm:h-16",
          className,
        )}
        style={
          containerMode === "absolute" && autoScale < 1
            ? {
                transform: `scale(${autoScale})`,
                transformOrigin:
                  position === "bottom-right" ? "bottom right" : "bottom left",
              }
            : undefined
        }
        {...props}
      >
        <style>{FCB_CSS}</style>
        {panelMounted && (
          <div
            data-state={isOpen ? "open" : "closed"}
            onTransitionEnd={(e) => {
              if (
                e.target === e.currentTarget &&
                e.propertyName === "opacity" &&
                !isOpen
              ) {
                setPanelMounted(false);
              }
            }}
            className={cn(
              "fcb-panel pointer-events-auto absolute bottom-full mb-3 sm:mb-4 rounded-2xl sm:rounded-3xl overflow-hidden border border-border/80 bg-background shadow-2xl flex flex-col transition-colors duration-300",
              modalAlignmentClasses,
              modalWidthClass,
              modalHeightClass,
            )}
          >
            <div
              style={{ backgroundColor: resolveColor(accentColor) }}
              className="p-4 sm:p-5 text-primary-foreground flex items-center justify-between relative overflow-hidden shrink-0 transition-colors duration-300"
            >
              <div className="absolute -right-10 -top-10 w-32 h-32 rounded-full bg-white/10 blur-xl pointer-events-none" />
              <div className="flex items-center gap-3 z-10 min-w-0">
                <div className="relative shrink-0">
                  <img
                    src={avatarUrl}
                    alt="Support Avatar"
                    className="w-9 h-9 sm:w-10 sm:h-10 rounded-full object-cover border-2 border-white/20 shadow-md"
                  />
                  <span className="absolute bottom-0 right-0 w-2.5 h-2.5 sm:w-3 sm:h-3 rounded-full bg-emerald-400 border-2 border-primary-foreground" />
                </div>
                <div className="flex flex-col min-w-0">
                  <div className="flex items-center gap-1.5">
                    <h3 className="font-semibold text-xs sm:text-sm tracking-tight truncate text-primary-foreground">
                      {title}
                    </h3>
                    <Sparkles className="w-3.5 h-3.5 opacity-80 shrink-0 animate-pulse text-primary-foreground" />
                  </div>
                  <p className="text-[10px] sm:text-[11px] opacity-90 truncate font-medium text-primary-foreground">
                    {subtitle}
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-black/10 hover:bg-black/20 flex items-center justify-center text-primary-foreground transition-colors cursor-pointer shrink-0 z-10"
              >
                <X className="w-4 h-4 stroke-[2.5]" />
              </button>
            </div>

            {/* Sandboxed scroll container ref attached directly here */}
            <div
              ref={scrollContainerRef}
              className="flex-1 p-3 sm:p-4 overflow-y-auto flex flex-col gap-3 sm:gap-3.5 bg-muted/50"
            >
              <div className="text-center my-1">
                <span className="text-[10px] font-mono font-semibold uppercase tracking-widest px-2.5 py-1 rounded-full bg-muted/60 text-muted-foreground">
                  Today
                </span>
              </div>

              {messages.map((msg) => {
                const isUser = msg.sender === "user";
                return (
                  <div
                    key={msg.id}
                    className={cn(
                      "fcb-message flex flex-col max-w-[85%]",
                      isUser
                        ? "self-end items-end"
                        : "self-start items-start",
                    )}
                  >
                    <div
                      style={{
                        backgroundColor: isUser
                          ? resolveColor(accentColor)
                          : undefined,
                      }}
                      className={cn(
                        "px-3.5 py-2 sm:px-4 sm:py-2.5 rounded-2xl text-xs sm:text-sm leading-relaxed shadow-sm transition-colors duration-300 break-words whitespace-pre-wrap max-w-full",
                        isUser
                          ? "rounded-br-xs font-medium text-primary-foreground"
                          : "bg-card border border-border/80 text-foreground rounded-bl-xs",
                      )}
                    >
                      {msg.text}
                    </div>
                    <div className="flex items-center gap-1 mt-1 px-1">
                      <span className="text-[10px] text-muted-foreground font-mono">
                        {msg.timestamp}
                      </span>
                      {isUser && (
                        <CheckCheck className="w-3 h-3 text-emerald-500 shrink-0" />
                      )}
                    </div>
                  </div>
                );
              })}

              {isTyping && (
                <div
                  className="fcb-typing self-start flex items-center gap-2 px-4 py-3 rounded-2xl rounded-bl-xs bg-card border border-border/80 shadow-sm"
                >
                  <Bot className="w-4 h-4 text-muted-foreground animate-bounce shrink-0" />
                  <div className="flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground animate-pulse" />
                    <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground animate-pulse delay-75" />
                    <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground animate-pulse delay-150" />
                  </div>
                </div>
              )}
            </div>

            <form
              onSubmit={handleSend}
              className="p-2.5 sm:p-3 bg-background border-t border-border/80 flex items-center gap-2 shrink-0"
            >
              <input
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Write a message..."
                className="flex-1 h-9 sm:h-10 px-3 sm:px-3.5 text-xs sm:text-sm bg-muted border border-transparent focus:border-border rounded-xl outline-none text-foreground placeholder:text-muted-foreground transition-all"
              />
              <button
                type="submit"
                disabled={!inputValue.trim()}
                style={{
                  backgroundColor: inputValue.trim()
                    ? resolveColor(accentColor)
                    : undefined,
                }}
                className={cn(
                  "w-9 h-9 sm:w-10 sm:h-10 rounded-xl flex items-center justify-center transition-all duration-200 cursor-pointer shrink-0",
                  inputValue.trim()
                    ? "text-primary-foreground shadow-md hover:opacity-90 scale-105"
                    : "bg-muted text-muted-foreground/60 cursor-not-allowed",
                )}
              >
                <Send className="w-3.5 h-3.5 sm:w-4 sm:h-4 stroke-[2.5]" />
              </button>
            </form>
          </div>
        )}

        <button
          type="button"
          onClick={() => setIsOpen(!isOpen)}
          style={{ backgroundColor: resolveColor(accentColor) }}
          className={cn(
            "fcb-launcher pointer-events-auto absolute inset-0 flex items-center justify-center rounded-full text-primary-foreground shadow-2xl transition-colors duration-300 cursor-pointer outline-none",
          )}
        >
          <div
            style={{ backgroundColor: activeBgGlow }}
            className="absolute inset-0 rounded-full blur-xl -z-10 group-hover:blur-2xl transition-all duration-300"
          />

          <div
            key={shownIcon}
            data-icon={shownIcon}
            data-leaving={iconLeaving || undefined}
            onTransitionEnd={(e) => {
              if (
                e.target === e.currentTarget &&
                e.propertyName === "opacity" &&
                iconLeaving
              ) {
                setShownIcon(wantedIcon);
              }
            }}
            className={cn("fcb-icon", shownIcon === "open" && "relative")}
          >
            {shownIcon === "close" ? (
              <X className="w-6 h-6 sm:w-7 sm:h-7 stroke-[2.5]" />
            ) : (
              <>
                <MessageSquare className="w-6 h-6 sm:w-7 sm:h-7 stroke-[2.2]" />
                <span className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-rose-500 ring-2 ring-primary-foreground animate-pulse" />
              </>
            )}
          </div>
        </button>
      </div>
    );
  },
);

FloatingContactButtonBlock.displayName = "FloatingContactButtonBlock";

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
